<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
$env=GreenPortalDatabase::env();$summary=[];
foreach(['gatlas_dbp','gmodelo_dbp','gmodelo2_dbp'] as $database){$pdo=GreenPortalDatabase::connect($env,$database,'GPT');$find=$pdo->prepare('SELECT CODTIPODOCUMENTO FROM li_tipos_documentos WHERE DSCTIPODOCUMENTO=? LIMIT 1');$find->execute(['Licença Ambiental']);$generic=(int)$find->fetchColumn();$find->execute(['Licença Ambiental de Operação']);$operation=(int)$find->fetchColumn();$find->execute(['Licença Ambiental de Instalação']);$installation=(int)$find->fetchColumn();$changed=0;if($generic&&$operation){$q=$pdo->prepare("UPDATE li_licencas SET CODTIPODOCUMENTO=? WHERE CODTIPODOCUMENTO=? AND UPPER(CONVERT(DSCLICENCA USING utf8mb4)) LIKE '%OPERAÇÃO%'");$q->execute([$operation,$generic]);$changed+=(int)$q->rowCount();$q=$pdo->prepare("UPDATE li_licencas SET CODTIPODOCUMENTO=? WHERE CODTIPODOCUMENTO=? AND UPPER(CONVERT(DSCLICENCA USING utf8mb4)) LIKE '%OPERACAO%'");$q->execute([$operation,$generic]);$changed+=(int)$q->rowCount();}if($generic&&$installation){$q=$pdo->prepare("UPDATE li_licencas SET CODTIPODOCUMENTO=? WHERE CODTIPODOCUMENTO=? AND (UPPER(CONVERT(DSCLICENCA USING utf8mb4)) LIKE '%INSTALAÇÃO%' OR UPPER(CONVERT(DSCLICENCA USING utf8mb4)) LIKE '%INSTALACAO%')");$q->execute([$installation,$generic]);$changed+=(int)$q->rowCount();}$pdo->prepare("INSERT INTO registros_migracao(codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES('GREEN_LICENSE_TYPES_CLASSIFICATION_FIX_228','li_licencas','li_licencas.CODTIPODOCUMENTO','DADOS','4.0.1','CONCLUIDA',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=VALUES(quantidade_registros),concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)")->execute([$changed,json_encode(['correcao'=>'precedencia_tipos_especificos'],JSON_UNESCAPED_UNICODE)]);$summary[$database]=['corrigidas'=>$changed];}
echo json_encode(['ok'=>true,'migration'=>228,'targets'=>$summary],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;
